+    /**
+     * Checks repository health once per given absolute path and JVM instance.
+     * Does not normalize symlinks.
+     */
+    @Override
+    public boolean isHealthyOnce() throws IOException {
+        if (!Files.exists(dir)) {
+            healthySet.remove(dir);
+            return false;
+        }
+        if (healthySet.contains(dir)) {
+            return true;
+        }
+        if (!isHealthy()) {
+            return false;
+        }
+        healthySet.add(dir);
+        return true;
+    }
